def render_invoice(items, tax_rate):
    if not items:
        return 'empty'
    lines = ['INVOICE']
    subtotal = 0
    for name, price in items:
        line = f'{name}: {price:.2f}'
        subtotal += price
        lines.append(line)
    total = round(subtotal * (1 + tax_rate), 2)
    lines.append(f'TOTAL: {total:.2f}')
    return '\n'.join(lines)

