def flatten(d, parent=''):
    out = {}
    for k, v in d.items():
        key = f'{parent}.{k}' if parent else k
        if isinstance(v, dict):
            out.update(flatten(v, key))
        else:
            out[key] = v
    return out

def top_k(nums, k):
    from collections import Counter
    return [x for x, _ in sorted(Counter(nums).items(), key=lambda kv: (-kv[1], kv[0]))[:k]]

def lis(nums):
    import bisect
    tails = []
    for n in nums:
        i = bisect.bisect_left(tails, n)
        if i == len(tails):
            tails.append(n)
        else:
            tails[i] = n
    return len(tails)

def can_reach(begin, end, words):
    from collections import deque
    words = set(words) | {begin}
    if end not in words:
        return False
    q, seen = deque([begin]), {begin}
    while q:
        w = q.popleft()
        if w == end:
            return True
        for i in range(len(w)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                n = w[:i] + c + w[i+1:]
                if n in words and n not in seen:
                    seen.add(n)
                    q.append(n)
    return False

